package com.lucid.os.island;
import android.app.Service;import android.content.Intent;import android.graphics.Color;import android.graphics.PixelFormat;import android.graphics.drawable.GradientDrawable;import android.os.IBinder;import android.view.Gravity;import android.view.View;import android.view.WindowInsets;import android.view.WindowManager;import android.widget.LinearLayout;import android.widget.TextView;
public final class IslandService extends Service {
 public static final String ACTION_TOGGLE="com.lucid.os.island.TOGGLE";private WindowManager wm;private View island;private boolean expanded;
 @Override public void onCreate(){super.onCreate();wm=(WindowManager)getSystemService(WINDOW_SERVICE);}
 @Override public int onStartCommand(Intent i,int f,int id){if(i!=null&&ACTION_TOGGLE.equals(i.getAction())){if(island==null)show();else if(expanded)remove();else{expanded=true;render();}}return START_NOT_STICKY;}
 private void show(){expanded=false;LinearLayout box=new LinearLayout(this);box.setGravity(Gravity.CENTER);box.setOrientation(0);box.setPadding(dp(15),dp(5),dp(15),dp(5));box.setElevation(dp(5));box.setBackground(shape());island=box;WindowManager.LayoutParams p=new WindowManager.LayoutParams(dp(118),dp(32),WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_LAYOUT_IN_SCREEN,PixelFormat.TRANSLUCENT);p.gravity=Gravity.TOP|Gravity.CENTER_HORIZONTAL;
 try{WindowInsets in=wm.getCurrentWindowMetrics().getWindowInsets();android.graphics.Insets cut=in.getInsetsIgnoringVisibility(WindowInsets.Type.displayCutout());android.graphics.Insets status=in.getInsetsIgnoringVisibility(WindowInsets.Type.statusBars());p.y=Math.max(dp(2),Math.min(cut.top>0?cut.top:status.top,dp(32))-dp(9));}catch(Exception e){p.y=dp(5);}try{wm.addView(island,p);render();}catch(Exception e){island=null;stopSelf();}}
 private GradientDrawable shape(){GradientDrawable d=new GradientDrawable();d.setColor(Color.rgb(15,15,22));d.setCornerRadius(dp(32));return d;}
 private void render(){if(island==null)return;LinearLayout b=(LinearLayout)island;b.removeAllViews();b.setBackground(shape());WindowManager.LayoutParams p=(WindowManager.LayoutParams)b.getLayoutParams();if(expanded){b.setOrientation(1);b.setPadding(dp(16),dp(8),dp(16),dp(8));b.addView(label("L U C I D",0xffb8a5ff,10));b.addView(label("Camera cutout companion",Color.WHITE,12));p.width=dp(224);p.height=dp(68);}else{b.setOrientation(0);b.setPadding(dp(15),dp(5),dp(15),dp(5));b.addView(label("●",0xff65e7ee,11));TextView t=label("LUCID",Color.WHITE,10);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-2,-2);lp.leftMargin=dp(5);b.addView(t,lp);p.width=dp(118);p.height=dp(32);}try{wm.updateViewLayout(island,p);}catch(Exception ignored){}}
 private TextView label(String s,int c,int z){TextView t=new TextView(this);t.setText(s);t.setTextColor(c);t.setTextSize(z);t.setGravity(Gravity.CENTER);return t;}private int dp(float n){return (int)(n*getResources().getDisplayMetrics().density+0.5f);}
 private void remove(){removeView();stopSelf();}private void removeView(){if(island!=null){try{wm.removeView(island);}catch(Exception ignored){}island=null;}}@Override public void onDestroy(){removeView();super.onDestroy();}@Override public IBinder onBind(Intent i){return null;}
}
